<?php
require_once __DIR__.'/includes/functions.php';if(logged_in())redirect('dashboard.php');$pageTitle='Create account — DriveEase';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$cnic=trim($_POST['cnic']??'');$address=trim($_POST['address']??'');$password=$_POST['password']??'';
if($name===''||mb_strlen($name)>120)$errors[]='Enter your full name.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email address.';if(strlen($password)<8)$errors[]='Password must be at least 8 characters.';if($phone==='')$errors[]='Phone number is required.';
if(!$errors){$s=db()->prepare('SELECT id FROM users WHERE email=?');$s->execute([$email]);if($s->fetch())$errors[]='An account with this email already exists.';}
if(!$errors){$s=db()->prepare("INSERT INTO users (name,email,password_hash,phone,cnic,address,role) VALUES (?,?,?,?,?,?,'customer')");$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$phone,$cnic?:null,$address?:null]);$id=(int)db()->lastInsertId();session_regenerate_id(true);$_SESSION['user']=['id'=>$id,'name'=>$name,'email'=>$email,'role'=>'customer'];log_activity('Registered account',$id);flash('success','Welcome to DriveEase. Your account is ready.');redirect('dashboard.php');}}
require __DIR__.'/includes/header.php'; ?>
<section class="auth-section"><div class="auth-card auth-card-wide"><div class="auth-intro"><span class="eyebrow">JOIN DRIVE EASE</span><h1>Your next journey starts here.</h1><p>Create an account to request reservations and manage your rental history.</p><div class="auth-decoration">D</div></div><div class="auth-form"><h2>Create your account</h2><p class="muted">All fields marked with * are required.</p><?php if($errors): ?><div class="alert alert-danger"><ul><?php foreach($errors as $er): ?><li><?= e($er) ?></li><?php endforeach; ?></ul></div><?php endif; ?><form method="post" class="form-stack"><?= csrf_field() ?><label>Full name *<input required name="name" maxlength="120" value="<?= e($_POST['name']??'') ?>" autocomplete="name"></label><label>Email address *<input required type="email" name="email" value="<?= e($_POST['email']??'') ?>" autocomplete="email"></label><div class="form-row"><label>Phone number *<input required name="phone" value="<?= e($_POST['phone']??'') ?>" autocomplete="tel"></label><label>CNIC (optional)<input name="cnic" value="<?= e($_POST['cnic']??'') ?>" placeholder="XXXXX-XXXXXXX-X"></label></div><label>Address (optional)<textarea name="address" rows="2"><?= e($_POST['address']??'') ?></textarea></label><label>Password *<input required type="password" name="password" minlength="8" autocomplete="new-password"><small class="muted">Use at least 8 characters.</small></label><button class="btn btn-primary btn-block btn-large">Create account ↗</button></form><p class="auth-switch">Already registered? <a href="<?= e(url('login.php')) ?>">Sign in</a></p></div></div></section>
